-- =====================================================================================
-- V16: XpressBees B2B activation (+ 3 generic engine features it needs).
-- Source of truth: XPRESSBEES/II Rate Quote.xlsx (sheets "Rate Quotation", "Vas's") - confirmed by
-- the business on 2026-11-09 over the commercial-proposal PDF where the two differ (fuel 25% not 20%,
-- Kerala/J&K Rs 2/kg not Rs 1/kg, ODA-2 Rs 7/kg min 1,500 not Rs 5/kg min 1,200).
-- Pincode categories: XPRESSBEES/B2B Pincode - Oct'2026.xlsx ("Oda/Long Category": Normal / ODA1 / ODA2).
-- =====================================================================================

-- ---- 1. Engine extensions (generic) ----
-- CALC_TYPE TOP_UP        : max(0, FIXED_AMOUNT - base). Minimum on selected lines only (TopUpChargeHandler).
-- BASE ACTUAL_WEIGHT      : total dead weight of all packages, kg.
-- APPLIES_WHEN DEST_STATE : destination STATE_ID = APPLIES_VALUE.
-- APPLIES_WHEN PIECE_WEIGHT_OVER : any piece dead weight > APPLIES_VALUE kg.
-- SO_RATE_CARD.MAX_PIECE_WEIGHT_KG : heavier single piece = not quoted (PieceWeightRule).
ALTER TABLE SO_RATE_CHARGE_RULE DROP CONSTRAINT SO_CK_RATE_RULE_CALC;
ALTER TABLE SO_RATE_CHARGE_RULE
    ADD CONSTRAINT SO_CK_RATE_RULE_CALC CHECK (CALC_TYPE IN ('FLAT', 'PERCENT', 'PER_UNIT', 'TOP_UP'));

ALTER TABLE SO_RATE_CHARGE_RULE DROP CONSTRAINT SO_CK_RATE_RULE_BASE;
ALTER TABLE SO_RATE_CHARGE_RULE
    ADD CONSTRAINT SO_CK_RATE_RULE_BASE CHECK (BASE IN ('BASE_FREIGHT', 'CHARGE_CODES', 'COD_AMOUNT', 'DECLARED_VALUE',
                                                        'CHARGEABLE_WEIGHT', 'ACTUAL_WEIGHT', 'NONE'));

ALTER TABLE SO_RATE_CHARGE_RULE DROP CONSTRAINT SO_CK_RATE_RULE_APPLIES;
ALTER TABLE SO_RATE_CHARGE_RULE DROP CONSTRAINT SO_CK_RATE_RULE_APPLIES_VALUE;
ALTER TABLE SO_RATE_CHARGE_RULE
    ADD CONSTRAINT SO_CK_RATE_RULE_APPLIES CHECK (APPLIES_WHEN IN ('ALWAYS', 'COD', 'PREPAID', 'ODA_DESTINATION', 'ODA_PICKUP',
                                                               'SPECIAL_CITY', 'RISK_OWNER', 'RISK_CARRIER',
                                                               'ADDON_OTP', 'ADDON_QC', 'ADDON_FRAGILE', 'CATEGORY',
                                                               'DEST_STATE', 'PIECE_WEIGHT_OVER')),
    ADD CONSTRAINT SO_CK_RATE_RULE_APPLIES_VALUE CHECK (APPLIES_WHEN NOT IN ('CATEGORY', 'DEST_STATE', 'PIECE_WEIGHT_OVER')
                                                        OR APPLIES_VALUE IS NOT NULL);

ALTER TABLE SO_RATE_CARD ADD COLUMN MAX_PIECE_WEIGHT_KG NUMERIC(10, 3);

-- ---- 2. XpressBees card ----
-- MIN_BILL 0: the Rs 350 minimum is on waybill + basic freight only -> MIN_FREIGHT TOP_UP rule below
--   (the card MIN_BILL compared the whole pre-tax total incl. fuel and FOV, which under-quoted).
-- MAX_WEIGHT_KG 3000: proposal "Maximum Weight per Waybill: up to 3000 kg" (xlsx gives none; V14 assumed 5000).
-- MAX_PIECE_WEIGHT_KG 100: xlsx "Actual weight above 100 kg, any piece: crane / MHE charges on actuals"
--   -> cannot be priced, so not quoted.
UPDATE SO_RATE_CARD
SET MIN_BILL = 0, MAX_WEIGHT_KG = 3000, MAX_PIECE_WEIGHT_KG = 100, UPDATED_AT = CURRENT_TIMESTAMP
WHERE ID = (SELECT c.ID FROM SO_RATE_CARD c JOIN SO_RATE_SERVICE s ON s.ID = c.SERVICE_ID WHERE s.PARTNER_ID = 14 AND s.SERVICE_CODE = 'B2B_SURFACE' AND c.VERSION_LABEL = 'XB-B2B-2026-10');

-- ---- 3. Extra XpressBees charge rules (V14 already has ODA destination 10, STATE_SURCHARGE 20,
--         FUEL_SURCHARGE 30 = 25% of basic, FOV 50 = Rs 100, WAYBILL 60 = Rs 100) ----
-- ODA 11       : ODA-1 at the PICKUP pincode, same rate (Rs 3/kg, min Rs 800); merges into the ODA line.
-- MIN_FREIGHT 70: "Min Freight (Waybill + Basic Rates Only) Rs 350" -> max(0, 350 - (BASE + WAYBILL)).
--                Fuel stays 25% of the actual basic freight (xlsx: "Fuel Surcharge (On Basic rates)").
-- GREEN_TAX 80 : Rs 100 per waybill, delivery within Delhi state (STATE_ID 32).
-- HEAVY_HANDLING 90: any piece over 50 kg -> Rs 1/kg on the total actual weight
--                (PERCENT 100% of ACTUAL_WEIGHT = Rs 1 x kg). Pieces over 100 kg are not quoted (card limit).
INSERT INTO SO_RATE_CHARGE_RULE (RATE_CARD_ID, CHARGE_CODE, SEQ, CALC_TYPE, RATE_VALUE, FIXED_AMOUNT, MIN_AMOUNT, MAX_AMOUNT,
                                 BASE, BASE_CODES, TIER_FROM, TIER_TO, APPLIES_WHEN, APPLIES_VALUE, DIRECTIONS)
SELECT (SELECT c.ID FROM SO_RATE_CARD c JOIN SO_RATE_SERVICE s ON s.ID = c.SERVICE_ID WHERE s.PARTNER_ID = 14 AND s.SERVICE_CODE = 'B2B_SURFACE' AND c.VERSION_LABEL = 'XB-B2B-2026-10'), v.CODE, v.SEQ, v.CALC, CAST(v.RATE AS NUMERIC), CAST(v.FIXED AS NUMERIC), CAST(v.MN AS NUMERIC), NULL,
       v.BASE, v.BC, NULL, NULL, v.AP, v.AV, v.DIRS
FROM (VALUES ('ODA',            11, 'PER_UNIT', 3,   0,   800,  'NONE',          NULL,           'ODA_PICKUP',        NULL, 'FORWARD,RTO'),
             ('MIN_FREIGHT',    70, 'TOP_UP',   0,   350, NULL, 'CHARGE_CODES',  'BASE,WAYBILL', 'ALWAYS',            NULL, 'FORWARD,RTO'),
             ('GREEN_TAX',      80, 'FLAT',     0,   100, NULL, 'NONE',          NULL,           'DEST_STATE',        '32', 'FORWARD'),
             ('HEAVY_HANDLING', 90, 'PERCENT',  100, 0,   NULL, 'ACTUAL_WEIGHT', NULL,           'PIECE_WEIGHT_OVER', '50', 'FORWARD'))
     AS v(CODE, SEQ, CALC, RATE, FIXED, MN, BASE, BC, AP, AV, DIRS);

