-- Pickup is Normal but delivery is ODA-2 (2 pincodes): delivery is off above; their single ODA flag
-- came from the delivery sheet, so clear it or pickups there would be charged ODA wrongly.
UPDATE SO_PARTNER_PINCODE SET ODA = FALSE
WHERE PARTNER_ID = 14 AND PINCODE IN (
    '248011', '803118'
);

